(function () {
	tinymce.PluginManager.add("uploadimage", function (editor) {

		//
		// 1. Your upload logic (XHR / fetch / formdata)
		//
		async function uploadFile(file) {
			const form = new FormData();
			form.append("file", file);
			form.append("alt", ""); // optional
			form.append("authenticity_token", Keystone.csrf.header["x-csrf-token"]);
			form.append("utf8", "✓");

			const response = await fetch(
				editor.getParam("uploadimage_form_url", "/tinymce_assets"),
				{ method: "POST", body: form }
			);

			if (!response.ok) {
				throw new Error("Upload failed (HTTP " + response.status + ")");
			}

			const json = await response.json();

			if (json.error) {
				throw new Error(json.error.message);
			}

			return json.image.url;
		}

		//
		// 2. Show dialog with urlinput + alt field
		//
		function openDialog() {
			editor.windowManager.open({
				title: "Insert image",
				size: "normal",

				body: {
					type: "panel",
					items: [
						{
							type: "urlinput",
							name: "src",
							filetype: "image"
						},
						{
							type: "input",
							name: "alt",
							label: "Image description"
						}
					]
				},

				buttons: [
					{ type: "cancel", text: "Cancel" },
					{ type: "submit", text: "Insert", buttonType: "primary" }
				],

				//
				// 3. Handle submit: insert image
				//
				onSubmit: function (api) {
					const data = api.getData();
					if (!data.src) {
						editor.windowManager.alert("Please choose an image");
						return;
					}

					editor.insertContent(
						`<img src="${editor.dom.encode(data.src.value)}" alt="${editor.dom.encode(data.alt || "")}" />`
					);

					api.close();
				}
			});
		}

		//
		// 4. intercept file_selection → upload → return URL
		//
		editor.options.register("file_picker_callback", {
			processor: "function",
			default: async (callback, value, meta) => {
				if (meta.filetype !== "image") return;

				const input = document.createElement("input");
				input.type = "file";
				input.accept = "image/*";

				input.onchange = async () => {
					const file = input.files[0];
					try {
						const url = await uploadFile(file);
						callback(url, { alt: file.name });
					} catch (e) {
						editor.windowManager.alert("Upload failed: " + e.message);
					}
				};

				input.click();
			},
		});

		//
		// 5. Toolbar + menu
		//
		editor.ui.registry.addButton("uploadimage", {
			icon: "image",
			tooltip: "Insert an image",
			onAction: openDialog
		});

		editor.ui.registry.addMenuItem("uploadimage", {
			icon: "image",
			text: "Insert an image",
			onAction: openDialog
		});

		return {
			getMetadata: function () {
				return {
					name: "Upload image plugin",
				};
			}
		};
	});
})();
